<?php

declare(strict_types=1);
require_once __DIR__.'/../includes/bootstrap.php';
require_role('ADMIN');

$productId=(int)($_GET['id']??$_POST['product_id']??0);
$product=$productId>0?admin_product_by_id($productId):null;
if($productId>0 && !$product){ http_response_code(404); $pageTitle='Product not found'; require __DIR__.'/../includes/header.php'; ?><div class="portal-shell"><?php require __DIR__.'/../includes/sidebar.php'; ?><main class="portal-main"><div class="empty-state"><i class="bi bi-cup-hot"></i><h1>Product not found.</h1><a class="btn btn-coffee" href="<?=url('admin/products.php')?>">Back to products</a></div></main></div><?php require __DIR__.'/../includes/footer.php'; exit; }

$inlineErrors=[];
if(is_post()){
    verify_csrf_or_abort(); $action=(string)($_POST['action']??'');
    if($action==='save_product'){
        $result=admin_save_product($_POST,$_FILES['image']??null,$productId);
        if($result['ok']){ flash('success',$result['message']); redirect('admin/product-form.php?id='.(int)$result['id']); }
        $inlineErrors=$result['errors'];
        $product=array_merge($product??[],$_POST,['id'=>$productId]);
    } elseif($productId>0 && $action==='remove_image') {
        $result=admin_remove_product_image($productId); flash($result['ok']?'success':'error',$result['message']); redirect('admin/product-form.php?id='.$productId);
    } elseif($productId>0 && in_array($action,['save_size','save_addon'],true)) {
        $type=$action==='save_size'?'size':'addon'; $optionId=(int)($_POST['option_id']??0); $result=admin_save_product_option($type,$productId,$_POST,$optionId);
        if(!$result['ok']) { $_SESSION['_option_errors']=$result['errors']; $_SESSION['_option_form']=$_POST; $_SESSION['_option_type']=$type; }
        else flash('success',$result['message']);
        redirect('admin/product-form.php?id='.$productId);
    } elseif($productId>0 && in_array($action,['toggle_size','toggle_addon'],true)) {
        $type=$action==='toggle_size'?'size':'addon'; $result=admin_toggle_product_option($type,$productId,(int)($_POST['option_id']??0)); flash($result['ok']?'success':'error',$result['message']); redirect('admin/product-form.php?id='.$productId);
    }
}

$product=$productId>0?admin_product_by_id($productId):($product??null);
$categories=admin_categories();
$sizes=$productId>0?admin_product_sizes($productId):[]; $addons=$productId>0?admin_product_addons($productId):[];
$optionErrors=$_SESSION['_option_errors']??[]; $optionForm=$_SESSION['_option_form']??[]; $optionType=$_SESSION['_option_type']??''; unset($_SESSION['_option_errors'],$_SESSION['_option_form'],$_SESSION['_option_type']);
$editSizeId=(int)($_GET['size_edit']??0); $editAddonId=(int)($_GET['addon_edit']??0);
$editingSize=$editSizeId>0?admin_option_by_id('size',$editSizeId,$productId):null; $editingAddon=$editAddonId>0?admin_option_by_id('addon',$editAddonId,$productId):null;
if($optionType==='size') $editingSize=array_merge($editingSize??[],$optionForm);
if($optionType==='addon') $editingAddon=array_merge($editingAddon??[],$optionForm);
$pageTitle=$productId>0?'Edit '.($product['name']??'Product'):'Add Product'; $bodyClass='portal-page'; require __DIR__.'/../includes/header.php'; $success=flash('success');$error=flash('error');
$p=$product??['name'=>'','category_id'=>'','description'=>'','base_price'=>'','prep_minutes'=>10,'is_active'=>1,'is_featured'=>0,'image_path'=>null];
?>
